    structure:[{title:"Sinai Organization",chapters:"1–10",description:"Census, camp, Levites, purity, offerings, Passover and departure."},{title:"Wilderness Rebellion",chapters:"11–20",description:"Complaints, spies, rebellion, Korah, priestly authority, Miriam's death and water from the rock."},{title:"Transjordan",chapters:"21–25",description:"Serpents, victories, Balaam and Baal Peor."},{title:"Preparation for Entry",chapters:"26–36",description:"Second census, leadership, offerings, Midian, Transjordan and land laws."}],
